<?php
namespace App\Services;use App\Core\Database;use RuntimeException;
class InventoryService{public function ensureDefault(int $env):int{$db=Database::connection();$s=$db->prepare('SELECT id FROM inventarios WHERE entorno_id=:e AND activo=1 ORDER BY id LIMIT 1');$s->execute(['e'=>$env]);$id=$s->fetchColumn();if($id)return(int)$id;$s=$db->prepare('INSERT INTO inventarios(entorno_id,nombre,descripcion,activo) VALUES(:e,"Inventario principal","Inventario general",1)');$s->execute(['e'=>$env]);return(int)$db->lastInsertId();}public function movement(array $d,int $env,int $by):void{$db=Database::connection();$inv=(int)($d['inventario_id']??$this->ensureDefault($env));$prod=(int)($d['producto_id']??0);$type=(int)($d['tipo_movimiento_id']??0);$qty=(float)($d['cantidad']??0);if(!$prod||!$type||$qty<=0)throw new RuntimeException('Producto, tipo y cantidad son obligatorios.');$s=$db->prepare('SELECT 1 FROM inventarios WHERE id=:i AND entorno_id=:e');$s->execute(['i'=>$inv,'e'=>$env]);if(!$s->fetchColumn())throw new RuntimeException('Inventario no válido.');$db->prepare('INSERT IGNORE INTO inventario_productos(inventario_id,producto_id,activo) VALUES(:i,:p,1)')->execute(['i'=>$inv,'p'=>$prod]);$db->prepare('INSERT INTO movimientos_inventario(inventario_id,producto_id,lote_id,tipo_movimiento_id,cantidad,costo_unitario,realizado_por,fecha_movimiento,observaciones) VALUES(:i,:p,:l,:t,:c,:co,:u,:f,:o)')->execute(['i'=>$inv,'p'=>$prod,'l'=>!empty($d['lote_id'])?(int)$d['lote_id']:null,'t'=>$type,'c'=>$qty,'co'=>($d['costo_unitario']??'')!==''?(float)$d['costo_unitario']:null,'u'=>$by,'f'=>date('Y-m-d H:i:s'),'o'=>trim((string)($d['observaciones']??''))?:null]);(new AuditService())->log($by,$env,'INVENTARIO','MOVIMIENTO','movimientos_inventario',(int)$db->lastInsertId());}}
